// Ping's spoken lines. One shared <audio> element, so two clips can never play at once.
// Files: public/voice/<voiceKey(text)>.mp3, durations in public/voice/index.json
// (generated by tools/narration – lines without a recording simply stay silent).
import { voiceKey } from './voiceKey';
import { duckMusic } from './audio';
import { useSettings } from '../game/settings';
import { useGame } from '../game/store';
import { logWarn } from '../game/log';

const BASE = `${import.meta.env.BASE_URL}voice/`;
let manifest = {};
fetch(`${BASE}index.json`)
  .then((r) => (r.ok ? r.json() : {}))
  .then((m) => { manifest = m || {}; })
  .catch(() => logWarn('narration', 'voice/index.json missing – narration off'));

const player = typeof Audio !== 'undefined' ? new Audio() : null;
if (player) {
  player.preload = 'auto';
  player.addEventListener('ended', () => duckMusic(false));
  player.addEventListener('pause', () => duckMusic(false));
}

export const narrationOn = () => useSettings.getState().narration !== false && !useGame.getState().muted;

/** Seconds the recording of this text lasts (0 if there is none or narration is off). */
export function voiceDuration(text) {
  if (!narrationOn()) return 0;
  return manifest[voiceKey(text)] || 0;
}

export function playVoice(text) {
  if (!player) return;
  stopVoice();
  if (!narrationOn()) return;
  const key = voiceKey(text);
  if (!manifest[key]) return;
  player.src = `${BASE}${key}.mp3`;
  player.volume = 0.95;
  duckMusic(true);
  player.play().catch(() => duckMusic(false)); // blocked before the first click – the bubble text is still there
}

export function stopVoice() {
  if (player && !player.paused) player.pause();
  duckMusic(false);
}
